INSERT INTO public.destinations ("id", "slug", "name", "country", "region", "continent", "short_description", "description", "hero_image", "best_season", "is_featured", "created_at")
VALUES
  ('73c23f4c-0be9-4485-9a34-0185e3070aa9', 'santorini', 'Santorini', 'Greece', 'Cyclades', 'Europe', 'Whitewashed cliffs above a sunken volcano.', 'Santorini rises from the Aegean in a crescent of black cliffs crowned with sugar-cube villages. Watch the caldera turn gold at sunset from Oia, swim from volcanic beaches, and eat tomato fritters in Fira.', 'https://images.unsplash.com/photo-1570077188670-e3a8d69ac5ff?auto=format&fit=crop&w=1920&q=80', 'April – October', true, '2026-08-31T20:06:42.553114+00:00'),
  ('9580e4cf-0238-4e55-bfe2-e1056622561a', 'kyoto', 'Kyoto', 'Japan', 'Kansai', 'Asia', 'Temples, tea houses and bamboo light.', 'Kyoto holds a thousand years of Japanese ritual in its wooden lanes. Follow torii tunnels up Fushimi Inari, drift through Arashiyama bamboo, and take dinner in a Gion machiya.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1920&q=80', 'March – May, October – November', true, '2026-08-31T20:06:42.553114+00:00'),
  ('e10be609-7bc1-420b-a834-4906ed1ef1aa', 'bali', 'Bali', 'Indonesia', 'Lesser Sunda', 'Asia', 'Rice terraces, reef breaks and temples.', 'Bali layers volcanic ridgelines, emerald rice terraces and a Hindu calendar of offerings. Surf Uluwatu at dawn, hike Batur by torchlight.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1920&q=80', 'April – October', true, '2026-08-31T20:06:42.553114+00:00'),
  ('84e0bf9c-0f52-48ef-8100-09f38c8d1323', 'iceland', 'Iceland', 'Iceland', 'Southern Region', 'Europe', 'Waterfalls, lava fields and aurora.', 'Iceland is geology in real time — black sand coasts, steaming valleys, glacier tongues and, in winter, green fire overhead.', 'https://images.unsplash.com/photo-1504829857797-ddff29c27927?auto=format&fit=crop&w=1920&q=80', 'June – August, February for aurora', true, '2026-08-31T20:06:42.553114+00:00'),
  ('95e8db5d-6362-42ed-8cb6-b4bd8be44cd5', 'serengeti', 'Serengeti', 'Tanzania', 'Mara', 'Africa', 'Endless plains and the great migration.', 'Two million wildebeest move in a slow wheel across the Serengeti. Balloon over the plains at sunrise, track cats in the Seronera valley.', 'https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=1920&q=80', 'June – October', false, '2026-08-31T20:06:42.553114+00:00'),
  ('6580b0bc-6dac-4dc3-ae3a-dce5a3e94f9c', 'queenstown', 'Queenstown', 'New Zealand', 'Otago', 'Oceania', 'Adventure capital on a glacial lake.', 'Framed by the Remarkables, Queenstown does adrenaline and pinot noir in equal measure.', 'https://images.unsplash.com/photo-1507699622108-4be3abd695ad?auto=format&fit=crop&w=1920&q=80', 'December – March', false, '2026-08-31T20:06:42.553114+00:00'),
  ('cfa7162c-6b00-4fb5-b8f0-18f2de950222', 'banff', 'Banff', 'Canada', 'Alberta', 'North America', 'Turquoise lakes under the Rockies.', 'Glacier-fed lakes so blue they look edited, larch valleys in autumn and elk on the town edge.', 'https://images.unsplash.com/photo-1609825488888-3a766db05542?auto=format&fit=crop&w=1920&q=80', 'June – September', false, '2026-08-31T20:06:42.553114+00:00'),
  ('ac4a6e70-166d-4a3d-bcd3-9c99a1d21dbd', 'lisbon', 'Lisbon', 'Portugal', 'Lisboa', 'Europe', 'Tiled hills above the Tagus.', 'Seven hills, yellow trams, pastel de nata and fado drifting out of Alfama doorways.', 'https://images.unsplash.com/photo-1585208798174-6cedd86e019a?auto=format&fit=crop&w=1920&q=80', 'March – June, September – October', false, '2026-08-31T20:06:42.553114+00:00'),
  ('236d5c38-7d67-486d-9e26-c10ef877d63a', 'maldives', 'Maldives', 'Maldives', 'North Malé Atoll', 'Asia', 'Atolls, overwater villas and reef.', 'A thousand coral islands scattered across the Indian Ocean; the water reads every shade of blue at once.', 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=1920&q=80', 'November – April', false, '2026-08-31T20:06:42.553114+00:00'),
  ('7aeb3ca0-8d64-45cf-b1c2-101e7979a25c', 'marrakech', 'Marrakech', 'Morocco', 'Marrakesh-Safi', 'Africa', 'Souks, riads and the Atlas skyline.', 'The red city hums. Trade for lanterns in the souks, cool off in a tiled riad courtyard, and cross the High Atlas to Berber villages.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=1920&q=80', 'March – May, September – November', true, '2026-08-31T20:06:42.553114+00:00'),
  ('39da55fd-7d0b-4e3f-8602-f06021057ff0', 'amalfi-coast', 'Amalfi Coast', 'Italy', 'Campania', 'Europe', 'Lemon groves stacked over blue water.', 'Cliffside towns, ceramic domes and a coast road built for slow driving. Positano to Ravello in a day, gelato at every stop.', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1920&q=80', 'May – September', false, '2026-08-31T20:06:42.553114+00:00'),
  ('02d92475-aac0-4e24-b311-e7e76b6e52d7', 'patagonia', 'Patagonia', 'Chile', 'Magallanes', 'South America', 'Granite towers, glaciers and wind.', 'At the end of the Americas, Patagonia is all scale: the Paine massif, calving glaciers, guanacos on the steppe and a sky that changes four times an hour.', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?auto=format&fit=crop&w=1920&q=80', 'November – March', true, '2026-08-31T20:06:42.553114+00:00')
INSERT INTO public.tour_packages ("id", "destination_id", "title", "slug", "summary", "description", "duration_days", "price_per_person", "difficulty", "group_size_max", "includes", "excludes", "itinerary", "image_url", "status", "is_featured", "created_at")
VALUES
  ('31fbf4ef-e328-4609-8d39-954f1c6ce2a2', '73c23f4c-0be9-4485-9a34-0185e3070aa9', 'Santorini Caldera Escape', 'santorini-caldera-escape', 'Five slow days of cliff villages, catamaran sunsets and volcanic wine.', 'Five slow days of cliff villages, catamaran sunsets and volcanic wine.', 5, 1290, 'easy', 12, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Arrival in Fira","description":"Transfer, caldera walk and welcome dinner."},{"day":2,"title":"Oia & sunset","description":"Village morning, blue-dome lanes, sunset viewpoint."},{"day":3,"title":"Catamaran day","description":"Hot springs, Red Beach, lunch aboard."},{"day":4,"title":"Wine & volcano","description":"Assyrtiko tasting and Nea Kameni hike."},{"day":5,"title":"Departure","description":"Free morning, transfer to airport."}]'::jsonb, 'https://images.unsplash.com/photo-1613395877344-13d4a8e0d49e?auto=format&fit=crop&w=1200&q=80', 'published', true, '2026-08-31T20:06:42.553114+00:00'),
  ('aa679567-f74d-46d0-a2c2-88feb0b6658f', '9580e4cf-0238-4e55-bfe2-e1056622561a', 'Kyoto Temples & Tea', 'kyoto-temples-and-tea', 'Seven days through shrines, bamboo groves and a Gion tea ceremony.', 'Seven days through shrines, bamboo groves and a Gion tea ceremony.', 7, 1980, 'easy', 10, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Arrival","description":"Machiya check-in and Pontocho stroll."},{"day":2,"title":"Fushimi Inari","description":"Sunrise torii climb and Tofukuji gardens."},{"day":3,"title":"Arashiyama","description":"Bamboo grove, monkey park, boat ride."},{"day":4,"title":"Tea ceremony","description":"Gion tea house and Kiyomizu-dera."},{"day":5,"title":"Nara day trip","description":"Todai-ji and deer park."},{"day":6,"title":"Kinkaku-ji","description":"Golden Pavilion and Nishiki market."},{"day":7,"title":"Departure","description":"Transfer to Kansai airport."}]'::jsonb, 'https://images.unsplash.com/photo-1545569341-9eb8b30979d9?auto=format&fit=crop&w=1200&q=80', 'published', true, '2026-08-31T20:06:42.553114+00:00'),
  ('d1496105-939e-4c26-b0f9-1c6fc81ce152', '02d92475-aac0-4e24-b311-e7e76b6e52d7', 'Torres del Paine W Trek', 'torres-del-paine-w-trek', 'Eight days hiking the W circuit with refugio nights and glacier views.', 'Eight days hiking the W circuit with refugio nights and glacier views.', 8, 2450, 'challenging', 8, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Puerto Natales","description":"Briefing and gear check."},{"day":2,"title":"Base Torres","description":"Climb to the granite towers."},{"day":3,"title":"Cuernos","description":"Lakeshore traverse."},{"day":4,"title":"French Valley","description":"Hanging glacier amphitheatre."},{"day":5,"title":"Grey Glacier","description":"Ice viewpoints and suspension bridges."},{"day":6,"title":"Catamaran out","description":"Cross Lake Pehoe."},{"day":7,"title":"Steppe wildlife","description":"Guanaco and condor spotting."},{"day":8,"title":"Departure","description":"Transfer to Punta Arenas."}]'::jsonb, 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=80', 'published', true, '2026-08-31T20:06:42.553114+00:00'),
  ('7dcb1e6d-9d21-46f9-98e6-641e9c57e928', '7aeb3ca0-8d64-45cf-b1c2-101e7979a25c', 'Marrakech & Atlas Villages', 'marrakech-and-atlas-villages', 'Six days of souks, riads and a High Atlas trek to Berber hamlets.', 'Six days of souks, riads and a High Atlas trek to Berber hamlets.', 6, 1140, 'moderate', 12, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Medina arrival","description":"Riad check-in, Jemaa el-Fnaa at dusk."},{"day":2,"title":"Souk day","description":"Guided market walk and Bahia Palace."},{"day":3,"title":"To the Atlas","description":"Drive to Imlil, village walk."},{"day":4,"title":"Trek","description":"Mule-supported hike between hamlets."},{"day":5,"title":"Hammam","description":"Return to Marrakech, spa afternoon."},{"day":6,"title":"Departure","description":"Transfer to airport."}]'::jsonb, 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=1200&q=80', 'published', true, '2026-08-31T20:06:42.553114+00:00'),
  ('22c62871-f5e4-45b7-b3b5-30cf45c3e43f', 'e10be609-7bc1-420b-a834-4906ed1ef1aa', 'Bali Rice Terraces & Reef', 'bali-rice-terraces-and-reef', 'Nine days from Ubud rice fields to Nusa Penida snorkelling.', 'Nine days from Ubud rice fields to Nusa Penida snorkelling.', 9, 1620, 'easy', 14, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Arrival Ubud","description":"Rice-field villa check-in."},{"day":2,"title":"Tegallalang","description":"Terrace walk and coffee estate."},{"day":3,"title":"Temples","description":"Tirta Empul and Goa Gajah."},{"day":4,"title":"Batur sunrise","description":"Volcano hike by torchlight."},{"day":5,"title":"To the coast","description":"Transfer to Sanur."},{"day":6,"title":"Nusa Penida","description":"Kelingking and manta snorkel."},{"day":7,"title":"Uluwatu","description":"Cliff temple and kecak dance."},{"day":8,"title":"Free day","description":"Surf or spa."},{"day":9,"title":"Departure","description":"Transfer to Denpasar."}]'::jsonb, 'https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?auto=format&fit=crop&w=1200&q=80', 'published', true, '2026-08-31T20:06:42.553114+00:00'),
  ('b0d23309-dc52-4195-91ba-9b99e8523e2a', '84e0bf9c-0f52-48ef-8100-09f38c8d1323', 'Iceland Ring Road Highlights', 'iceland-ring-road-highlights', 'Ten days of waterfalls, glacier lagoons and black sand coastline.', 'Ten days of waterfalls, glacier lagoons and black sand coastline.', 10, 2890, 'moderate', 10, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Reykjavik","description":"Arrival and harbour walk."},{"day":2,"title":"Golden Circle","description":"Thingvellir, Geysir, Gullfoss."},{"day":3,"title":"South coast","description":"Seljalandsfoss and Skogafoss."},{"day":4,"title":"Vik","description":"Reynisfjara black sand."},{"day":5,"title":"Jokulsarlon","description":"Glacier lagoon and Diamond Beach."},{"day":6,"title":"East fjords","description":"Coastal driving day."},{"day":7,"title":"Myvatn","description":"Geothermal fields and baths."},{"day":8,"title":"Akureyri","description":"Whale watching."},{"day":9,"title":"Snaefellsnes","description":"Kirkjufell and lava coast."},{"day":10,"title":"Departure","description":"Return to Keflavik."}]'::jsonb, 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=1200&q=80', 'published', true, '2026-08-31T20:06:42.553114+00:00'),
  ('bafba489-79f5-42f9-bcaf-379137a5e7d6', '39da55fd-7d0b-4e3f-8602-f06021057ff0', 'Amalfi Slow Coast', 'amalfi-slow-coast', 'Six days between Positano, Ravello and a Capri boat day.', 'Six days between Positano, Ravello and a Capri boat day.', 6, 1750, 'easy', 12, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Positano","description":"Arrival and beach evening."},{"day":2,"title":"Path of the Gods","description":"Cliff-top hike to Nocelle."},{"day":3,"title":"Amalfi & Ravello","description":"Duomo and Villa Cimbrone gardens."},{"day":4,"title":"Capri","description":"Private boat and Blue Grotto."},{"day":5,"title":"Cooking class","description":"Lemon grove lunch."},{"day":6,"title":"Departure","description":"Transfer to Naples."}]'::jsonb, 'https://images.unsplash.com/photo-1534445867742-43195f401b6c?auto=format&fit=crop&w=1200&q=80', 'published', false, '2026-08-31T20:06:42.553114+00:00'),
  ('1ba56211-9dcb-4ad7-a62b-2d6e071d66af', '95e8db5d-6362-42ed-8cb6-b4bd8be44cd5', 'Serengeti Migration Safari', 'serengeti-migration-safari', 'Eight days tracking the herds with balloon sunrise and Ngorongoro.', 'Eight days tracking the herds with balloon sunrise and Ngorongoro.', 8, 4320, 'moderate', 6, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Arusha","description":"Briefing and lodge night."},{"day":2,"title":"Tarangire","description":"Elephant herds and baobabs."},{"day":3,"title":"To Serengeti","description":"Afternoon game drive."},{"day":4,"title":"Seronera","description":"Big cat tracking."},{"day":5,"title":"Balloon sunrise","description":"Flight and bush breakfast."},{"day":6,"title":"Migration","description":"Follow the herds north."},{"day":7,"title":"Ngorongoro","description":"Crater floor drive."},{"day":8,"title":"Departure","description":"Return to Arusha."}]'::jsonb, 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?auto=format&fit=crop&w=1200&q=80', 'published', false, '2026-08-31T20:06:42.553114+00:00'),
  ('64235ac3-2832-4973-bb55-2fb527cbead8', '6580b0bc-6dac-4dc3-ae3a-dce5a3e94f9c', 'Queenstown Adventure Week', 'queenstown-adventure-week', 'Seven days of Milford Sound, jet boats and alpine trails.', 'Seven days of Milford Sound, jet boats and alpine trails.', 7, 2190, 'moderate', 10, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Arrival","description":"Lakefront evening."},{"day":2,"title":"Ben Lomond","description":"Alpine day hike."},{"day":3,"title":"Milford Sound","description":"Fiord cruise."},{"day":4,"title":"Shotover","description":"Jet boat and canyon."},{"day":5,"title":"Glenorchy","description":"Paradise valley drive."},{"day":6,"title":"Wine day","description":"Gibbston pinot tasting."},{"day":7,"title":"Departure","description":"Transfer to airport."}]'::jsonb, 'https://images.unsplash.com/photo-1589802829985-817e51171b92?auto=format&fit=crop&w=1200&q=80', 'published', false, '2026-08-31T20:06:42.553114+00:00'),
  ('17316aa4-856c-4059-b3b5-bef9b0a7228c', 'cfa7162c-6b00-4fb5-b8f0-18f2de950222', 'Rockies Lakes & Larches', 'rockies-lakes-and-larches', 'Six days around Louise, Moraine and the Icefields Parkway.', 'Six days around Louise, Moraine and the Icefields Parkway.', 6, 1980, 'moderate', 12, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Banff","description":"Town arrival and gondola."},{"day":2,"title":"Lake Louise","description":"Teahouse hike."},{"day":3,"title":"Moraine Lake","description":"Larch valley trail."},{"day":4,"title":"Icefields Parkway","description":"Peyto and Athabasca."},{"day":5,"title":"Johnston Canyon","description":"Ink pots walk and hot springs."},{"day":6,"title":"Departure","description":"Transfer to Calgary."}]'::jsonb, 'https://images.unsplash.com/photo-1561134643-668f9057cce4?auto=format&fit=crop&w=1200&q=80', 'published', false, '2026-08-31T20:06:42.553114+00:00'),
  ('d65db865-2c0f-475a-8edb-c50e05a3a58d', 'ac4a6e70-166d-4a3d-bcd3-9c99a1d21dbd', 'Lisbon & Sintra Weekend', 'lisbon-and-sintra-weekend', 'Four days of trams, tiles, fado and a Sintra palace day.', 'Four days of trams, tiles, fado and a Sintra palace day.', 4, 780, 'easy', 14, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Alfama","description":"Tram 28 and fado dinner."},{"day":2,"title":"Belem","description":"Tower, monastery, pasteis."},{"day":3,"title":"Sintra","description":"Pena Palace and Quinta da Regaleira."},{"day":4,"title":"Departure","description":"Time-Out market and transfer."}]'::jsonb, 'https://images.unsplash.com/photo-1555881400-74d7acaacd8b?auto=format&fit=crop&w=1200&q=80', 'published', false, '2026-08-31T20:06:42.553114+00:00'),
  ('4f254a28-feb6-4089-95d0-5ef3349c5615', '236d5c38-7d67-486d-9e26-c10ef877d63a', 'Maldives Reef Retreat', 'maldives-reef-retreat', 'Five days of overwater calm, manta snorkelling and sandbank picnics.', 'Five days of overwater calm, manta snorkelling and sandbank picnics.', 5, 3150, 'easy', 8, '["Accommodation","Daily breakfast","Local guide","Airport transfers"]'::jsonb, '["International flights","Travel insurance","Personal expenses"]'::jsonb, '[{"day":1,"title":"Arrival","description":"Seaplane transfer and villa."},{"day":2,"title":"House reef","description":"Guided snorkel."},{"day":3,"title":"Manta point","description":"Boat trip and sandbank lunch."},{"day":4,"title":"Spa day","description":"Overwater treatment and sunset sail."},{"day":5,"title":"Departure","description":"Seaplane to Male."}]'::jsonb, 'https://images.unsplash.com/photo-1573843981267-be1999ff37cd?auto=format&fit=crop&w=1200&q=80', 'published', false, '2026-08-31T20:06:42.553114+00:00')
INSERT INTO public.hotels ("id", "destination_id", "name", "description", "address", "star_rating", "price_per_night", "amenities", "image_url", "status", "created_at")
