  ('166328e7-50ac-44c8-ab0f-f52ea5ae65b0', '73c23f4c-0be9-4485-9a34-0185e3070aa9', 'Fira Terrace Hotel', 'Simple whitewashed rooms two minutes from the caldera path.', 'Fira, Santorini', 4, 190, '["Free Wi-Fi","Pool","Breakfast","Air conditioning","Spa"]'::jsonb, 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-31T20:06:42.553114+00:00'),
  ('31ab01f0-4072-4e5b-8672-435827b83f24', '73c23f4c-0be9-4485-9a34-0185e3070aa9', 'Caldera Blue Suites', 'Cave suites carved into the cliff with private plunge pools.', 'Oia, Santorini', 5, 420, '["Free Wi-Fi","Pool","Breakfast","Air conditioning","Spa"]'::jsonb, 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-31T20:06:42.553114+00:00'),
  ('628db8af-589d-457b-9746-e0797eb54faa', '9580e4cf-0238-4e55-bfe2-e1056622561a', 'Arashiyama Garden Inn', 'Quiet inn beside the bamboo grove with kaiseki breakfast.', 'Arashiyama, Kyoto', 4, 240, '["Free Wi-Fi","Pool","Breakfast","Air conditioning","Spa"]'::jsonb, 'https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-31T20:06:42.553114+00:00'),
  ('c18392ab-69c1-40cb-9493-2bc8f122f689', '9580e4cf-0238-4e55-bfe2-e1056622561a', 'Machiya Gion Ryokan', 'Restored townhouse with tatami rooms and a cedar bath.', 'Gion, Kyoto', 5, 380, '["Free Wi-Fi","Pool","Breakfast","Air conditioning","Spa"]'::jsonb, 'https://images.unsplash.com/photo-1578683010236-d716f9a3f461?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-31T20:06:42.553114+00:00'),
  ('ef96096d-6d4d-41cc-9994-454fe9c02bb2', '02d92475-aac0-4e24-b311-e7e76b6e52d7', 'Refugio Paine Lodge', 'Warm timber lodge at the trailhead with drying rooms.', 'Torres del Paine', 3, 150, '["Free Wi-Fi","Pool","Breakfast","Air conditioning","Spa"]'::jsonb, 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1200&q=80', 'published', '2026-08-31T20:06:42.553114+00:00'),
